import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, vec3, vec2, length, float } from 'three/tsl';
import { gsap } from 'gsap';

function hexToVec3(THREE, hex) {
  const c = new THREE.Color(hex);
  return vec3(c.r, c.g, c.b);
}

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();
  root.name = 'orbit-product-hero';

  const colors = config.intent?.visualSpec?.colors ?? config.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#0b0b10' }, { at: 0.55, hex: '#101017' }, { at: 1, hex: '#16161d' }],
  };

  const cleanupFns = [];
  const primitiveHandles = [];
  const gsapTimelines = [];

  // ---------------------------------------------------------------
  // BACKDROP (7x6 at z=-2.5) with engineered vertical gradient
  // ---------------------------------------------------------------
  const stops = colors.gradientStops ?? [
    { at: 0, hex: colors.background },
    { at: 0.55, hex: colors.surface },
    { at: 1, hex: colors.ink },
  ];
  const c0 = hexToVec3(THREE, stops[0].hex);
  const c1 = hexToVec3(THREE, stops[1] ? stops[1].hex : stops[0].hex);
  const c2 = hexToVec3(THREE, stops[2] ? stops[2].hex : stops[stops.length - 1].hex);

  const backdropGeo = new THREE.PlaneGeometry(7, 6, 1, 1);
  const backdropMat = new MeshBasicNodeMaterial();
  const t = uv().y;
  const stepA = stops[1]?.at ?? 0.55;
  const stepB = stops[2]?.at ?? 1.0;
  let gradient = mix(c0, c1, smoothstep(float(0.0), float(stepA), t));
  gradient = mix(gradient, c2, smoothstep(float(stepA), float(stepB), t));
  backdropMat.colorNode = gradient;
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------------------------------------------------------------
  // STAGE GROUP (plinth + watch + contact shadow) — orbits + tilts
  // ---------------------------------------------------------------
  const stageGroup = new THREE.Group();
  stageGroup.name = 'stage-group';
  root.add(stageGroup);

  // contact shadow (radial gradient plane) under plinth
  const shadowGeo = new THREE.PlaneGeometry(3.2, 3.2, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  const suv = uv().sub(vec2(0.5, 0.5));
  const dist = length(suv).mul(2.0);
  const alpha = smoothstep(float(1.0), float(0.0), dist).mul(0.55);
  shadowMat.colorNode = hexToVec3(THREE, '#000000');
  shadowMat.opacityNode = alpha;
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -1.349, 0);
  stageGroup.add(shadowMesh);

  // plinth: radius 1.4, height 0.25, top face at y=-1.1 -> center y=-1.225
  const plinthGeo = new THREE.CylinderGeometry(1.4, 1.4, 0.25, 48);
  const plinthMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(colors.surface || '#14141a'),
    roughness: 0.7,
    metalness: 0.3,
  });
  const plinth = new THREE.Mesh(plinthGeo, plinthMat);
  plinth.position.set(0, -1.225, 0);
  stageGroup.add(plinth);

  // watch mesh placeholder group (populated async via glbLoader)
  const watchSlot = new THREE.Group();
  watchSlot.name = 'watch-slot';
  stageGroup.add(watchSlot);

  const loadedDisposables = [];

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const scene = gltf.scene || gltf.scenes?.[0];
      if (!scene) return;

      // normalize to 2.2 units tall, centered at origin
      const box = new THREE.Box3().setFromObject(scene);
      const size = new THREE.Vector3();
      box.getSize(size);
      const scale = size.y > 0 ? 2.2 / size.y : 1;
      scene.scale.setScalar(scale);

      const box2 = new THREE.Box3().setFromObject(scene);
      const center = new THREE.Vector3();
      box2.getCenter(center);
      scene.position.x -= center.x;
      scene.position.z -= center.z;
      // rest bottom at plinth top y = -1.1
      scene.position.y -= box2.min.y;
      scene.position.y += -1.1;

      scene.traverse((child) => {
        if (child.isMesh && child.material) {
          const mats = Array.isArray(child.material) ? child.material : [child.material];
          mats.forEach((m) => {
            if ('roughness' in m) m.roughness = 0.52;
            if ('metalness' in m) m.metalness = 0.55;
            if ('clearcoat' in m) m.clearcoat = 0.2;
            if ('clearcoatRoughness' in m) m.clearcoatRoughness = 0.4;
            if ('anisotropy' in m) m.anisotropy = 0.8;
            m.needsUpdate = true;
          });
          loadedDisposables.push(child.geometry);
        }
      });

      watchSlot.add(scene);
    }).catch(() => {});
  }

  // ---------------------------------------------------------------
  // LIGHTING — node-local rim/accent only (ambient + key provided by scene)
  // ---------------------------------------------------------------
  const rimLight = new THREE.DirectionalLight(new THREE.Color(colors.accent || '#ff2a38'), 0.9);
  rimLight.position.set(-3.2, 1.4, 2.0);
  rimLight.target = watchSlot;
  root.add(rimLight);
  root.add(rimLight.target);

  // ---------------------------------------------------------------
  // TEXT CONTENT
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [
    { text: 'Calibre NA-01', role: 'headline', typography: { fontSize: 68 } },
    { text: 'Machined in-house. 41 mm. Grade 5 titanium.', role: 'body', typography: { fontSize: 26 } },
    { text: 'FROM 4200 USD / SHIPS IN 21 DAYS', role: 'caption', typography: { fontSize: 18 } },
  ];

  const textGroup = new THREE.Group();
  textGroup.name = 'text-group';
  root.add(textGroup);

  let headlineY = -1.5;
  const textObjects = [];
  for (const item of items) {
    const role = item.role || 'body';
    const fontSize = item.typography?.fontSize ?? (role === 'headline' ? 68 : role === 'caption' ? 18 : 26);
    let y;
    let color = colors.paper || '#e8ecf2';
    let letterSpacingPx = 0;
    if (role === 'headline') {
      y = headlineY;
    } else if (role === 'caption') {
      y = headlineY - 0.5;
      letterSpacingPx = fontSize * 0.08;
    } else {
      y = headlineY - 0.25;
    }
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color,
      align: 'center',
      letterSpacingPx,
    });
    textObj.position.set(0, y, 1.2);
    textGroup.add(textObj);
    textObjects.push(textObj);
  }

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES
  // ---------------------------------------------------------------
  const primitiveConfigs = config.cinematicPrimitives ?? [];

  const loadPrim = primitiveConfigs.find((p) => p.name === 'orbit' && p.trigger === 'load');
  if (loadPrim) {
    const r = ctx.primitives['orbit'](stageGroup, loadPrim.params ?? { speed: 0.15, radius: 0.6 });
    primitiveHandles.push(r);
  }

  const hoverPrim = primitiveConfigs.find((p) => p.name === 'depth-rotate' && p.trigger === 'hover');
  let activeHoverHandle = null;

  function onPointerOver() {
    if (!hoverPrim || activeHoverHandle) return;
    activeHoverHandle = ctx.primitives['depth-rotate'](stageGroup, hoverPrim.params ?? { maxDeg: 6 });
    primitiveHandles.push(activeHoverHandle);
  }

  function onPointerOut() {
    if (activeHoverHandle) {
      if (activeHoverHandle.timeline && typeof activeHoverHandle.timeline.reverse === 'function') {
        activeHoverHandle.timeline.reverse();
      }
      const settle = gsap.to(stageGroup.scale, {
        x: 1.0, y: 1.0, z: 1.0,
        duration: 0.9,
        ease: 'power4.out',
        onStart: () => {
          stageGroup.scale.setScalar(1.04);
        },
      });
      gsapTimelines.push(settle);
      activeHoverHandle = null;
    }
  }

  root.userData.handlers = {
    onPointerOver,
    onPointerOut,
    onPointerEnter: onPointerOver,
    onPointerLeave: onPointerOut,
  };

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const h of primitiveHandles) {
      try { h.cleanup?.(); } catch (e) {}
    }
    for (const tl of gsapTimelines) {
      try { tl.kill(); } catch (e) {}
    }

    backdropGeo.dispose();
    backdropMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    plinthGeo.dispose();
    plinthMat.dispose();

    for (const geo of loadedDisposables) {
      try { geo.dispose(); } catch (e) {}
    }

    for (const t of textObjects) {
      t.traverse?.((c) => {
        if (c.geometry) c.geometry.dispose?.();
        if (c.material) {
          const mats = Array.isArray(c.material) ? c.material : [c.material];
          mats.forEach((m) => m.dispose?.());
        }
      });
    }
  };

  return root;
}
